function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  const n = nums.length;
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v >= n)) return 'Each value is an integer from 0 to nums.length - 1.';
  return null;
}

