function countWays(nums) {
  nums.sort((a, b) => a - b);
  const n = nums.length;
  let ways = 0;

  for (let k = 0; k <= n; k++) {
    if (k > 0 && nums[k - 1] >= k) {
      continue;
    }
    if (k < n && nums[k] <= k) {
      continue;
    }
    ways++;
  }
  return ways;
}

