function countWays(nums) {
  // Try every subset of students as a bitmask and test every student.
  const n = nums.length;
  let count = 0;
  for (let mask = 0; mask < (1 << n); mask++) {
    let chosen = 0;
    for (let i = 0; i < n; i++) if (mask & (1 << i)) chosen++;
    let allHappy = true;
    for (let i = 0; i < n && allHappy; i++) {
      const inGroup = (mask & (1 << i)) !== 0;
      if (inGroup ? !(chosen > nums[i]) : !(chosen < nums[i])) allHappy = false;
    }
    if (allHappy) count++;
  }
  return count;
}

