function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 10);
  const nums = [];
  if (rand() < 0.4) {
    for (let i = 0; i < n; i++) nums.push(Math.floor(rand() * n));
  } else {
    // Build blocks so that several group sizes work: each block of g values sits strictly between two valid sizes.
    let prev = rand() < 0.5 ? 0 : -1;
    if (prev === -1) { nums.push(0); prev = 1; }
    while (nums.length < n) {
      const remaining = n - nums.length;
      const g = Math.min(remaining, 2 + Math.floor(rand() * (size === 'large' ? 12 : 3)));
      for (let t = 0; t < g; t++) {
        const low = Math.min(prev + 1, n - 1);
        const high = Math.min(prev + g - 1, n - 1);
        nums.push(low + Math.floor(rand() * (high - low + 1)));
      }
      prev += g;
    }
    // Occasionally spoil a few values so that some sizes stop working.
    const spoil = rand() < 0.5 ? Math.floor(rand() * 4) : 0;
    for (let t = 0; t < spoil; t++) nums[Math.floor(rand() * n)] = Math.floor(rand() * n);
    for (let i = n - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [nums[i], nums[j]] = [nums[j], nums[i]];
    }
  }
  return [nums];
}
